                                title="End Election"
                              >
                                <Square size={18} />
                              </button>
                            </>
                          )}

                          {election?.status === 'paused' && (
                            <>
                              <button
                                type="button"
                                onClick={() => handleElectionAction(election._id, 'start')}
                                className="icon-btn start"
                                title="Resume Election"
                              >
                                <Play size={18} />
                              </button>

                              <button
                                type="button"
                                onClick={() => handleElectionAction(election._id, 'end')}
                                className="icon-btn end"
                                title="End Election"
                              >
                                <Square size={18} />
